SELECT AVG(T1.payment_value * (T2.quantity / T3.stock_quantity)) AS avg_payment_value FROM order_payments AS T1 INNER JOIN (
    SELECT order_id, SUM(quantity) AS quantity FROM order_items GROUP BY order_id
) AS T2 ON T1.order_id = T2.order_id INNER JOIN (
    SELECT product_id, stock_quantity FROM products
) AS T3 ON T2.product_id = T3.product_id
